static void ex_words(const struct ln_ui_canvas_context *c){if(ex_phase==EX_LEVEL){static const char *const levels[]={"Easy  /  8 x 8  /  5 words","Medium  /  10 x 10  /  7 words","Hard  /  12 x 10  /  9 words"};ex_level(c,"Word Search",levels);return;}char hud[32],*p=hud;append(&p,"FOUND ");number(&p,ws_found);append(&p," / ");number(&p,ws_count);append(&p,"  ");number(&p,ws_elapsed);append(&p,"s");*p=0;ex_frame(c,"Word Search",hud);int32_t sidebar=LINNET_UI_WIDTH>250?94:76,cell=((int32_t)LINNET_UI_HEIGHT-58)/ws_h;if(cell>((int32_t)LINNET_UI_WIDTH-sidebar-12)/ws_w)cell=((int32_t)LINNET_UI_WIDTH-sidebar-12)/ws_w;int32_t x0=6,y0=28,list_x=x0+cell*ws_w+8;for(uint8_t y=0;y<ws_h;++y)for(uint8_t x=0;x<ws_w;++x){uint8_t at=y*ws_w+x;int32_t xx=x0+x*cell,yy=y0+y*cell;bool cursor=at==ws_cursor,found=ws_cell_found(at),preview=ws_cell_preview(at);uint16_t fill=preview?0x6a40u:found?0x238au:((x+y)&1u)?0x10a9u:0x10c9u;box(c,xx,yy,cell-1,cell-1,fill);if(cursor||at==ws_anchor){box(c,xx,yy,cell-1,1,ex_gold);box(c,xx,yy,1,cell-1,ex_gold);}char s[2]={ws_grid[at],0};arcade_center(c,xx+cell/2,yy+(cell-10)/2,s,preview||found?ex_white:ex_muted,true,1);}arcade_text(c,list_x,29,"FIND",ex_gold,true);for(uint8_t i=0;i<ws_count;++i){int32_t y=42+i*13;bool found=(ws_found_mask&(1u<<i))!=0;box(c,list_x,y+3,5,5,found?ex_green:ex_line);arcade_text(c,list_x+9,y,ws_words[ws_level][i],found?ex_green:ex_muted,true);}ex_footer(c,ws_anchor==255u?"Select: start word":"Select: finish / Play cancel","Wheel or </>: move");if(ex_phase==EX_WON)ex_overlay(c,"All words found","A clean sweep of the board.","Select  /  New puzzle");}
